    "到了八十五歲，他病重在床，"
    "臨終前寫下《示兒》這首詩：\n"
    "「死去元知萬事空，但悲不見九州同。"
    "王師北定中原日，家祭無忘告乃翁。」\n"
    "意思是：我知道死後萬事皆空，"
